// ─── File: SerializationDemo.java ───
// Single runnable file with multiple top-level package-private classes.
// Uses Jackson for polymorphic round-trip; shows Gson configuration too.
package com.bank.serial;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.BigDecimal;
import java.util.logging.*;

public class SerializationDemo {
    private static final Logger log = Logger.getLogger(SerializationDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // --- Jackson SERIALIZE: concrete subtype → JSON with a "type" discriminator ---
        Account savings = new SavingsAccount("SAV2001", new BigDecimal("1000000"));
        String json = mapper.writeValueAsString(savings);
        log.info(() -> "Serialized JSON = " + json);  // includes {"type":"SAVINGS", ...}

        // --- Jackson DESERIALIZE: JSON → correct permitted subtype via discriminator ---
        Account back = mapper.readValue(json, Account.class);
        log.info(() -> "Deserialized into " + back.getClass().getSimpleName()
                + " id=" + back.id() + " balance=Rs." + back.balance());

        // --- GSON configuration (no built-in polymorphism): RuntimeTypeAdapterFactory ---
        // (Pseudocode-style setup; requires gson + gson-extras on the classpath.)
        // RuntimeTypeAdapterFactory<Account> factory =
        //     RuntimeTypeAdapterFactory.of(Account.class, "type")
        //         .registerSubtype(SavingsAccount.class, "SAVINGS")
        //         .registerSubtype(CurrentAccount.class, "CURRENT")
        //         .registerSubtype(LoanAccount.class, "LOAN");
        // Gson gson = new GsonBuilder().registerTypeAdapterFactory(factory).create();
        // String g = gson.toJson(savings, Account.class);
        // Account gBack = gson.fromJson(g, Account.class);
        log.info(() -> "Gson needs RuntimeTypeAdapterFactory mapping type→subtype (see comments)");

        // --- SECURITY note: never enable Jackson default typing on untrusted JSON. ---
        // We only allow the KNOWN permitted subtypes via @JsonSubTypes name mapping.
        log.info(() -> "Only permitted subtypes are allowed — no arbitrary class instantiation");
    }
}

// ─── Would be in model/Account.java ───
// Discriminator "type" tells the deserializer which permitted subtype to build.
// Id.NAME maps names (not raw class names) → safe, controlled set only.
@JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.PROPERTY, property = "type")
@JsonSubTypes({
    @JsonSubTypes.Type(value = SavingsAccount.class, name = "SAVINGS"),
    @JsonSubTypes.Type(value = CurrentAccount.class, name = "CURRENT"),
    @JsonSubTypes.Type(value = LoanAccount.class,   name = "LOAN")
})
sealed interface Account permits SavingsAccount, CurrentAccount, LoanAccount {
    String id();
    BigDecimal balance();
}

// ─── Record leaves — Jackson binds via canonical constructor ───
record SavingsAccount(String id, BigDecimal balance) implements Account { }
record CurrentAccount(String id, BigDecimal balance) implements Account { }
record LoanAccount(String id, BigDecimal balance)   implements Account { }

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
